 1	import {addRoundUsage, shouldContinueToolLoop} from './orchestratorHelpers.js';
 2	import type {ToolRegistry} from './tools/registry.js';
 3	import type {ToolCall, TotalUsage, UsageMetadata} from '../types/ai.js';
 4	
 5	// All three conditions matter; dropping the registry check spins the tool loop.
 6	
 7	const A_TOOL: ToolCall[] = [{id: 't1', name: 'lookup', input: {}}];
 8	const REGISTRY = {} as ToolRegistry;
 9	
10	describe('shouldContinueToolLoop', () => {
11	  it('continues when the model requested a tool and a registry can run it', () => {
12	    expect(shouldContinueToolLoop('tool_use', A_TOOL, REGISTRY)).toBe(true);
13	  });
14	
15	  it('stops when no registry is configured, whatever the model asked for', () => {
16	    expect(shouldContinueToolLoop('tool_use', A_TOOL, undefined)).toBe(false);
17	  });
18	
19	  it('stops when the model named no tool', () => {
20	    expect(shouldContinueToolLoop('tool_use', [], REGISTRY)).toBe(false);
21	  });
22	
23	  it('stops when the model finished for a reason other than tool use', () => {
24	    expect(shouldContinueToolLoop('end_turn', A_TOOL, REGISTRY)).toBe(false);
25	  });
26	});
27	
28	const A_ROUND: UsageMetadata = {inputTokens: 11, outputTokens: 2, totalTokens: 13};
29	const A_TOTAL: TotalUsage = {inputTokens: 5, outputTokens: 1, totalTokens: 6};
30	
31	describe('addRoundUsage', () => {
32	  it('adds each token field of a round that reports to the running total', () => {
33	    expect(addRoundUsage(A_TOTAL, A_ROUND)).toEqual({inputTokens: 16, outputTokens: 3, totalTokens: 19});
34	  });
35	
36	  it('starts the total from the first round that reports', () => {
37	    expect(addRoundUsage(undefined, A_ROUND)).toEqual(A_ROUND);
38	  });
39	
40	  it('keeps the total when a round reports nothing', () => {
41	    expect(addRoundUsage(A_TOTAL, undefined)).toEqual(A_TOTAL);
42	  });
43	
44	  it('stays undefined while no round has reported', () => {
45	    expect(addRoundUsage(undefined, undefined)).toBeUndefined();
46	  });
47	});

