commit e7a102ae0c6b6ae331ee58806da38839b914e26a
Author: loop-bench <loop-bench@localhost>
Date:   Tue Oct 20 18:47:02 2026 +0200

    feat(orchestrator): sum usage across every tool round

    afterModelResponse received the last provider call's usage alone, so
    tool-heavy turns under-counted exactly their expensive legs. It now
    receives TotalUsage, each token field summed over every round that
    reported; rounds reporting nothing add nothing and a turn where none
    reported stays undefined. No-tool turns report what they did before.

    Refs #93

    Co-Authored-By: Claude Code <noreply@anthropic.com>

diff --git a/CHANGELOG.md b/CHANGELOG.md
index fda97c4..97a7a46 100644
--- a/CHANGELOG.md
+++ b/CHANGELOG.md
@@ -18,6 +18,7 @@ package, not for somebody reading this repository's commit log.

 - Every `SessionStore` member is now `Awaitable<T>` (`T | Promise<T>`) rather than a bare `T`, so a store backed by a database is expressible for the first time. `Awaitable` is exported from the package root. **A synchronous implementation needs no change** — `T` is assignable to `T | Promise<T>` in a return position — and `InMemorySessionStore` is unedited. The WebSocket connection handler now awaits `create` and the release that follows a close: it pauses the socket across the await so a frame sent before `connected` arrives is buffered rather than dropped, attaches its `close` listener before the await so a socket that closes mid-create leaves no session behind, and catches a rejection from either call so one store failure closes one socket instead of ending the process with an unhandled rejection. **Migration note**: the `connected` frame now arrives one tick later, after the awaited `create`, so a client that waits for it (as the protocol already requires) sees no difference; only code that assumed the frame was emitted synchronously with the upgrade does.
 - **The engine no longer erases a conversation when its socket closes.** The WebSocket close handler called `sessionStore.delete(sessionId)` unconditionally, which meant that behind a durable store every conversation was written and then destroyed the moment the customer closed their tab — the opposite of what this engine's own documentation promised. `SessionStore.delete` now has no engine-internal caller at all and is purely your erasure primitive. The credentials the socket carried are cleared from the session on close, since they were issued for a request that is over; the entries are untouched. **Migration note**: to restore the old behaviour exactly, pass `onDisconnect: sessionId => store.delete(sessionId)` — that one line is the whole migration. If you rely on the default store not growing, note that it is now bounded by `maxAgeMs` (eight hours) rather than by the close handler; that is a memory bound, not a retention policy, and the retention decision remains yours.
+- **`afterModelResponse` now receives the usage of the whole turn, not of its last provider call.** The hook fires once per user message, after the tool-round loop exits, and used to be handed the usage of the final provider call alone — so a turn that answered through tool rounds under-counted exactly its expensive legs, and the round carrying the customer's question and the full tool results was billed to nobody. It now receives a `TotalUsage` (new, exported from the package root): each token field summed over every provider call the turn made. A round whose provider reported no usage adds nothing rather than poisoning the total, and a turn where no round reported still reports `undefined`. **Migration note**: a turn with no tool calls reports exactly what it reported before; a tool-heavy turn reports a larger number to an existing consumer, which is the point — this is a behaviour change, released in a MINOR bump, so re-check any budget or threshold tuned on the old value.

 ### Fixed

diff --git a/specs/hal-engine-architecture/spec.md b/specs/hal-engine-architecture/spec.md
index 9e30580..d7165f5 100644
--- a/specs/hal-engine-architecture/spec.md
+++ b/specs/hal-engine-architecture/spec.md
@@ -196,7 +196,7 @@ interface OrchestratorHooks {
   beforeUserInput?: (session: ChatSession, userMessage: string) => Promise<string>;
   afterUserInput?: (session: ChatSession, userMessage: string) => Promise<void>;
   beforeModelResponse?: (session: ChatSession, systemPrompt: string) => Promise<string>;
-  afterModelResponse?: (session: ChatSession, responseText: string, usage?: UsageMetadata) => Promise<void>;
+  afterModelResponse?: (session: ChatSession, responseText: string, totalUsage?: TotalUsage) => Promise<void>;
   onError?: (session: ChatSession, error: Error) => Promise<void>;
   /** The supported seam for an EU AI Act Art. 14 human-oversight control: fires before each known tool's executor, and a returned ToolResponse replaces the call (see docs/adding-a-tool.md); it receives the model's raw tool input and, through session, the caller's authHeaders, so a policy that logs either logs personal data and credential material; the engine asserts nothing about any policy installed here. */
   beforeToolCall?: (session: ChatSession, call: ToolCall) => Promise<ToolResponse | undefined>;
diff --git a/specs/hal-engine-config-hooks/spec.md b/specs/hal-engine-config-hooks/spec.md
index fad014d..47c9a0f 100644
--- a/specs/hal-engine-config-hooks/spec.md
+++ b/specs/hal-engine-config-hooks/spec.md
@@ -24,5 +24,6 @@

 These properties of `src/orchestration/chatOrchestrator.ts` record the measured semantics that hook features specify against. The `onError` boundary remains out of scope; issue #93 defines the aggregate usage delivered after tool rounds.

-- The `catch` gates `onError` on `error instanceof Error` ([chatOrchestrator.ts#L150](../../src/orchestration/chatOrchestrator.ts#L150)), so a rejection that is not an `Error` — a thrown string or object — bypasses `onError` entirely while still propagating to the caller.
-- `afterModelResponse` is called once per user message after the round loop exits and receives the summed provider-call usage for the entire turn, so tool rounds are included in a deployer's billing or audit total ([validated by: reports the summed usage from every provider call in a turn with two tool rounds](../../src/orchestration/chatOrchestratorUsage.acceptance.test.ts#L44)).
+- The `catch` gates `onError` on `error instanceof Error` ([chatOrchestrator.ts#L151](../../src/orchestration/chatOrchestrator.ts#L151)), so a rejection that is not an `Error` — a thrown string or object — bypasses `onError` entirely while still propagating to the caller.
+- `afterModelResponse` is called once per user message after the round loop exits and receives the summed provider-call usage for the entire turn, typed `TotalUsage` so the sum is visible at the hook rather than only in the orchestrator, so tool rounds are included in a deployer's billing or audit total ([validated by: reports the summed usage from every provider call in a turn with two tool rounds](../../src/orchestration/chatOrchestratorUsage.acceptance.test.ts#L44)).
+- A round whose provider reports no usage adds nothing to that total, and a turn where no round reported still hands the hook `undefined` ([validated by: counts reported rounds while leaving a turn with no reported usage undefined](../../src/orchestration/chatOrchestratorUsage.acceptance.test.ts#L67)).
diff --git a/src/orchestration/orchestratorHelpers.ts b/src/orchestration/orchestratorHelpers.ts
index 717eb9a..c5fa9d4 100644
--- a/src/orchestration/orchestratorHelpers.ts
+++ b/src/orchestration/orchestratorHelpers.ts
@@ -1,4 +1,4 @@
-import type {Message, MessageChunk, ToolCall, UsageMetadata} from '../types/ai.js';
+import type {Message, MessageChunk, ToolCall, TotalUsage, UsageMetadata} from '../types/ai.js';
 import type {ToolRegistry} from './tools/registry.js';

 export function shouldContinueToolLoop(
@@ -40,3 +40,13 @@ export function extractStopReason(chunk: MessageChunk): string | null {
 export function extractUsage(chunk: MessageChunk): UsageMetadata | undefined {
   return chunk.type === 'stop' ? chunk.usage : undefined;
 }
+
+// A round that reports nothing adds nothing, so a turn where no round reported stays undefined.
+export function addRoundUsage(total: TotalUsage | undefined, round: UsageMetadata | undefined): TotalUsage | undefined {
+  if (!round) return total;
+  return {
+    inputTokens: (total?.inputTokens ?? 0) + round.inputTokens,
+    outputTokens: (total?.outputTokens ?? 0) + round.outputTokens,
+    totalTokens: (total?.totalTokens ?? 0) + round.totalTokens,
+  };
+}
diff --git a/src/types/ai.ts b/src/types/ai.ts
index 8c777fd..943e8c0 100644
--- a/src/types/ai.ts
+++ b/src/types/ai.ts
@@ -80,6 +80,13 @@ export interface UsageMetadata {
   totalTokens: number;
 }

+/** The summed token usage of every provider call one turn made; `undefined` when no call reported. */
+export interface TotalUsage {
+  inputTokens: number;
+  outputTokens: number;
+  totalTokens: number;
+}
+
 export interface AIProviderResponse {
   usage?: UsageMetadata;
 }

