let t = fs.readFileSync('specs/hal-engine-architecture/spec.md','utf8');
const before = statementCoverage(t);
console.log('before:', JSON.stringify(before), parseDocStatus(t,'spec').status);
const adds = [
  [32, 'adds each token field of a round that reports to the running total'],
  [36, 'starts the total from the first round that reports'],
  [40, 'keeps the total when a round reports nothing'],
  [44, 'stays undefined while no round has reported'],
];
for (const [line, name] of adds) {
  t += '\n- placeholder ' + name + ' ([validated by: ' + name + '](../../src/orchestration/orchestratorHelpers.test.ts#L' + line + ')).';
}
const after = statementCoverage(t);
console.log('after:', JSON.stringify(after), expectedStatus(coverageTier(after.testable, after.linked)));
"

